using System;using System.Drawing;using System.Reflection;using System.Windows.Forms;
class LayoutTests {
 [STAThread]static int Main(){using(var form=new InstallerWizard("v6.0.0")){var table=(TableLayoutPanel)form.Controls[0];var buttons=(FlowLayoutPanel)table.Controls[4];form.CreateControl();form.PerformLayout();table.PerformLayout();buttons.PerformLayout();if(table.GetRow(buttons)!=4)throw new Exception("Footer buttons do not have a reserved footer row; hidden progress can shift placement.");foreach(float scale in new[]{1f,1.25f,1.5f,2f}){form.ClientSize=new Size((int)(740*scale),(int)(560*scale));form.PerformLayout();table.PerformLayout();buttons.PerformLayout();foreach(Control b in buttons.Controls){if(b.Top<0||b.Bottom>buttons.ClientSize.Height||b.Height<b.GetPreferredSize(Size.Empty).Height)throw new Exception("Clipped action button at scale "+scale);}}}Console.WriteLine("PASS reserved footer row and unclipped action buttons across window sizes");return 0;}
}
